({__plugin:null,__load(){if(this.__plugin)return this.__plugin;this.__plugin=function(){"use strict";let locales=unbound.i18n.createLocales({COPIED:"Copied {code}"});locales.messages;let format=locales.format;function copyCode(code){unbound.metro.common.Clipboard.setString(code);var preview=code.length>40?`${code.slice(0,39)}…`:code;unbound.toasts.show({title:addon.name,content:format("COPIED",{code:preview})})}function wrapChat(chat){var original=chat.onTapInlineCode;chat.onTapInlineCode=event=>{var code=event?.nativeEvent?.node?.content;code?copyCode(code):original?.(event)}}function patchInlineCodeTaps(){var MessagesRenderer=unbound.metro.findByFilePath("modules/messages/native/MessagesRenderer.tsx");MessagesRenderer?.default?unbound.patcher.react.after(MessagesRenderer,"default",({result})=>{var chat=unbound.utils.react.findInTree(result,node=>"function"==typeof node?.onTapInlineCode);chat&&wrapChat(chat)}):logger.warn("Inline code taps skipped: Discord moved MessagesRenderer.")}return locales.useMessages,{start:function start(){patchInlineCodeTaps()},stop:function stop(){unbound.patcher.unpatchAll()}}}();return this.__plugin;}})